from pathlib import Path
import hashlib, json, re
root = Path('products/distribution/sqlite-community-directory')
source = root / 'raw/awesome-sqlite-readme.md'
result = {'source_url': 'https://github.com/planetopendata/awesome-sqlite', 'source_present': source.is_file(), 'sections': {}, 'contribution_references': [], 'existing_handoff_files': []}
if source.is_file():
    data = source.read_bytes()
    result['sha256'] = hashlib.sha256(data).hexdigest()
    section = ''
    for line in data.decode('utf-8').splitlines():
        if re.match(r'^#{1,6}\s+', line):
            section = line.lstrip('#').strip()
        if section in {'SQLite Admin Tools', 'Web', 'Desktop', 'Misc', 'SQLite Documentation / History'} and re.match(r'^\s*[-*]\s+\[', line):
            result['sections'].setdefault(section, []).append(line)
        if re.search(r'contribut|pull request|AI.generated', line, re.I):
            result['contribution_references'].append(line)
    result['sections'] = {name: {'entry_count': len(entries), 'examples': entries[:4]} for name, entries in result['sections'].items()}
for folder in (root, Path('products/services/sqlite-repair/bespoke-inbound')):
    if folder.is_dir():
        result['existing_handoff_files'].extend(str(p) for p in sorted(folder.iterdir()) if p.is_file())
output = root / 'director-placement-readback.json'
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(json.dumps({'source_present': result['source_present'], 'section_counts': {name: section['entry_count'] for name, section in result['sections'].items()}, 'contribution_reference_count': len(result['contribution_references']), 'evidence': str(output)}))
